#pragma once
namespace lj2 {
inline const char* dashboard(){return R"HTML(<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>留境 · 实景空间</title>
<style>*{box-sizing:border-box}body{margin:0;background:#10171d;color:#eef4f4;font:16px system-ui,sans-serif}main{max-width:1200px;margin:auto;padding:28px}header{display:flex;align-items:center;justify-content:space-between}h1{font-size:30px;margin:0}small,.muted{color:#9cafbb}.stage{margin:22px 0 16px;background:#05080b;border:1px solid #30414c;border-radius:14px;overflow:hidden;position:relative;min-height:280px}#frame{display:block;width:100%;max-height:65vh;object-fit:contain;aspect-ratio:4/3}.banner{position:absolute;left:14px;top:14px;padding:8px 12px;background:#111d;max-width:90%;border-radius:6px}#health{color:#ffcf7d}#metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:12px}.metric{padding:14px;background:#1b2832;border-radius:8px}.metric b{display:block;font-size:23px;margin-top:5px}.controls{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}button{background:#273a48;color:white;border:1px solid #48616f;border-radius:7px;padding:10px 15px;cursor:pointer}button:hover{background:#3e5664}button.primary{background:#236c65}pre{white-space:pre-wrap;max-height:260px;overflow:auto}#message{min-height:24px;color:#ffcf7d}footer{font-size:13px;color:#9cafbb;margin-top:18px}</style>
<main><header><div><h1>留境</h1><small>真实空间 · 板端建图 · FPGA 渲染</small></div><span id="cal">标定状态待读取</span></header>
<div class="stage"><img id="frame" alt="等待板端生成图像"><div class="banner" id="health">正在连接板端…</div></div><div id="metrics"></div>
<p class="muted">画面视角控制 · 只改变观察位置，不会驱动实体设备</p><div class="controls"><button id="v-follow" onclick="view('follow')">跟随</button><button id="v-top" onclick="view('top')">俯视</button><button id="v-free" class="primary" onclick="view('free')">自由视角</button><button onclick="move({dz:.2})">视角前移</button><button onclick="move({dz:-.2})">视角后移</button><button onclick="move({dx:-.2})">视角左移</button><button onclick="move({dx:.2})">视角右移</button><button onclick="move({yaw:-.15})">视角左转</button><button onclick="move({yaw:.15})">视角右转</button><button onclick="post('/save-map')">保存地图</button></div>
<div id="message"></div><details><summary>技术详情与验证</summary><p>CPU/PL 对拍会暂时占用处理资源，请在性能统计之外执行。</p><button onclick="post('/compare-next')">对拍下一次任务</button><pre id="details"></pre></details><footer>图像由 KV260 生成；网页仅放大显示。红色 UNVERIFIED 表示标定未核验，不能据此进行移动验收。</footer></main>
<script>
const $=id=>document.getElementById(id);let seq=-1,url='',history=[],lastArrival=0;
async function post(path,data){try{const r=await fetch(path,{method:'POST',body:data?JSON.stringify(data):undefined});const text=await r.text();if(!r.ok)throw Error(text);$('message').textContent=path==='/save-map'?'地图已保存：'+text:path==='/compare-next'?'已安排一次真实任务 CPU/PL 对拍':'';return text}catch(e){$('message').textContent='操作失败：'+e.message}}
function view(mode){return post('/view',{mode})}function move(d){return post('/view',{mode:'free',...d})}
function metric(label,value){return '<div class="metric"><small>'+label+'</small><b>'+value+'</b></div>'}
function resetDisplay(){seq=-1;history=[];lastArrival=0;$('frame').removeAttribute('src');if(url)URL.revokeObjectURL(url);url='';$('metrics').innerHTML=metric('板端新画面 / 秒','0.0')+metric('地图更新 / 秒','0.0')}
async function poll(){try{
 const r=await fetch('/status',{cache:'no-store',signal:AbortSignal.timeout(1000)});if(!r.ok)throw Error('status');const s=await r.json();const now=Number(s.mono);if(Number(s.new_frame||0)<seq||(history.length&&now<history[history.length-1].t))resetDisplay();lastArrival=performance.now();history.push({t:now,n:Number(s.new_frame||0),f:Number(s.fused||0)});while(history.length>1&&history[1].t<now-5)history.shift();const a=history[0],dt=now-a.t;const fps=dt>0?(Number(s.new_frame||0)-a.n)/dt:0,fhz=dt>0?(Number(s.fused||0)-a.f)/dt:0;
 $('metrics').innerHTML=metric('实际渲染尺寸',(s.frame_width||'—')+' × '+(s.frame_height||'—'))+metric('板端新画面 / 秒',fps.toFixed(1))+metric('地图更新 / 秒',fhz.toFixed(1))+metric('面元数量',Number(s.map_surfels||0).toLocaleString())+metric('PL 完成次数',s.pl_completed_jobs||0);
 const reasons={input_missing_or_clock_wait:'相机输入中断或时钟重新同步',budget_exceeded:'当前视角超预算',pose_missing_or_stale:'定位缺失或过期',waiting_for_map:'等待有效地图',fault:'运行故障'};const age=Number(s.frame_age_s??-1);for(const mode of ['follow','top','free'])$('v-'+mode).classList.toggle('primary',s.view_mode===mode);$('health').textContent=s.failure?'故障：'+s.failure:['budget_exceeded','input_missing_or_clock_wait'].includes(s.render_health)?'画面暂停 · '+reasons[s.render_health]:age<0?'等待首张真实画面':age>.5?'画面暂停 · '+(reasons[s.render_health]||'等待新画面')+' · 已 '+age.toFixed(1)+' 秒未更新':s.view_mode==='free'&&(Number(s.map_age_s)>1.5||s.render_health==='pose_missing_or_stale')?'自由视角 · 地图更新延迟 '+Number(s.map_age_s).toFixed(1)+' 秒':'实时画面 · '+({follow:'跟随',top:'俯视',free:'自由视角'}[s.view_mode]||'等待视角');
 $('cal').textContent=s.mode==='static_diagnostic'?'静止诊断 · 标定未核验':'真实输入 · 标定配置已核验';$('details').textContent=JSON.stringify(s,null,2);
 if(Number(s.new_frame)>0&&Number(s.new_frame)>seq){const im=await fetch('/frame.jpg',{cache:'no-store',signal:AbortSignal.timeout(1000)});if(!im.ok)throw Error('frame');{const next=URL.createObjectURL(await im.blob());$('frame').src=next;if(url)URL.revokeObjectURL(url);url=next;seq=Number(s.new_frame)}}
 }catch(e){resetDisplay();$('health').textContent='连接中断或会话已结束 · 已停止显示旧画面'}setTimeout(poll,50)}
setInterval(()=>{if(lastArrival&&performance.now()-lastArrival>1500){resetDisplay();$('health').textContent='板端状态超时 · 已停止显示旧画面'}},500);poll();
</script></html>)HTML";}
}
